const {app,BrowserWindow}=require('electron'),fs=require('node:fs'),path=require('node:path'),http=require('node:http'),assert=require('node:assert/strict')
const {BrowserSessionService}=require('../../desktop/services/browser-session.cjs')
const root=fs.mkdtempSync(path.join(require('node:os').tmpdir(),'stable-browser-test-'));app.setPath('userData',root);app.disableHardwareAcceleration()
const data=new Map(),store={getSetting:k=>data.get(k),setSetting:(k,v)=>data.set(k,structuredClone(v))};let service,win,server
async function main(){await app.whenReady();const downloads=path.join(root,'downloads');fs.mkdirSync(downloads);store.setSetting('browser-download-settings',{directory:downloads})
 server=http.createServer((req,res)=>{if(req.url==='/download'){res.writeHead(200,{'Content-Disposition':'attachment; filename="report.txt"','Content-Type':'application/octet-stream'});res.end('verified-report');return}if(req.url==='/frame'){res.end('<button onclick="this.innerText=String(Number(this.dataset.count||0)+1);this.dataset.count=this.innerText">Frame button</button>');return}res.setHeader('Content-Type','text/html; charset=utf-8');res.end('<title>Fixture</title><h1>共享页面</h1><input aria-label="姓名"><input type="password" aria-label="密码"><button onclick="document.querySelector(\'h1\').innerText=\'clicked\'">改变标题</button><a href="/download">下载报表</a><iframe src="/frame"></iframe>')});await new Promise(r=>server.listen(0,'127.0.0.1',r));const url='http://127.0.0.1:'+server.address().port
 win=new BrowserWindow({show:false,width:1000,height:800,webPreferences:{offscreen:true,sandbox:true}})
 service=new BrowserSessionService({electron:require('electron'),store,getWindow:()=>win});let snap=await service.execute('a',{action:'open',url});const tab=service.get('a',snap.tabId)
 service.show('a',tab.id,{x:0,y:0,width:900,height:700});assert(win.contentView.children.includes(tab.view));assert.match(snap.text,/共享页面/)
 const ref=snap.controls.find(c=>c.label==='姓名').ref;await service.execute('a',{action:'fill',tabId:tab.id,ref,value:'Alice'});assert.equal(await tab.view.webContents.executeJavaScript('document.querySelector("input").value'),'Alice')
 service.control('a',tab.id,true);for(const action of ['read','click','screenshot','history'])await assert.rejects(service.execute('a',{action,tabId:tab.id,ref}),/接管/)
 await service.profile.cookies.set({url,name:'login',value:'fixture',expirationDate:Date.now()/1000+3600});service.control('a',tab.id,false);await assert.rejects(service.execute('a',{action:'fill',ref,value:'stale'}),/失效/)
 snap=await service.execute('a',{action:'read'});await assert.rejects(service.execute('a',{action:'fill',ref:snap.controls.find(c=>c.type==='password').ref,value:'no'}),/敏感/)
 await assert.rejects(service.execute('b',{action:'read',tabId:tab.id}),/请先/)
 const frames=await service.execute('a',{action:'frames'});const frameId=frames.frameTree.childFrames[0].frame.id;const frame=await service.execute('a',{action:'read',frameId});assert.match(frame.text,/Frame button/);await assert.rejects(service.execute('a',{action:'key',frameId,ref:frame.controls[0].ref,value:'Enter'}),/展开浏览器/);const afterKey=await service.execute('a',{action:'read',frameId});await assert.rejects(service.execute('a',{action:'hover',frameId,ref:afterKey.controls[0].ref}),/展开浏览器/);const afterHover=await service.execute('a',{action:'read',frameId});await assert.rejects(service.execute('a',{action:'drag',frameId,ref:afterHover.controls[0].ref,targetRef:afterHover.controls[0].ref}),/展开浏览器/)
 snap=await service.execute('a',{action:'read'});await service.execute('a',{action:'click',ref:snap.controls.find(c=>c.label==='下载报表').ref});const until=Date.now()+5000;while(!service.downloads.list('a').some(d=>d.state==='completed')&&Date.now()<until)await new Promise(r=>setTimeout(r,50));let d=service.downloads.list('a')[0];assert.equal(d.state,'completed',JSON.stringify(d));assert.equal(fs.readFileSync(d.path,'utf8'),'verified-report');assert.equal(d.bytes,15)
 const workspace=path.join(root,'workspace');fs.mkdirSync(workspace);const imported=service.downloads.import(d.id,workspace);assert.equal(fs.readFileSync(imported.path,'utf8'),'verified-report');assert.notEqual(imported.path,d.path)
 await service.execute('a',{action:'history'}).then(()=>assert.fail('history permitted'),e=>assert.match(e.message,/单独授权/));service.store.setSetting('browser-history-allow:a',true);assert((await service.execute('a',{action:'history'})).history.length)
 service.annotate('a',tab.id,'Check numbers');assert.equal(store.getSetting('browser-annotations-v2')[0].tabId,tab.id)
 await service.navigate('a',tab.id,'open',url)
 // OAuth-style popup must retain window.opener, including postMessage and window.close.
 await tab.view.webContents.executeJavaScript(`window.popupMessage='';window.addEventListener('message',e=>window.popupMessage=e.data);window.open('/frame','loginPopup');true`)
 let popup;for(let i=0;i<60;i++){popup=[...service.tabs.values()].find(t=>t.id!==tab.id);if(popup&&!popup.view.webContents.isLoading()&&popup.view.webContents.getURL().endsWith('/frame'))break;await new Promise(r=>setTimeout(r,50))}
 assert(popup,'popup was not registered');assert.equal(await popup.view.webContents.executeJavaScript('!!window.opener'),true);await popup.view.webContents.executeJavaScript(`window.opener.postMessage('login-complete','*');true`)
 await new Promise(r=>setTimeout(r,50));assert.equal(await tab.view.webContents.executeJavaScript('window.popupMessage'),'login-complete');void popup.view.webContents.executeJavaScript('window.close();true').catch(()=>{});await new Promise(r=>setTimeout(r,50));assert(!service.tabs.has(popup.id))
 snap=await service.execute('a',{action:'read',tabId:tab.id});await assert.rejects(service.execute('a',{action:'key',tabId:tab.id,ref:snap.controls.find(c=>c.label==='姓名').ref,value:'Tab'}),/展开浏览器/);assert.equal(tab.state,'idle')
 service.hide();assert.equal((await service.profile.cookies.get({url,name:'login'}))[0].value,'fixture');service.dispose();service=new BrowserSessionService({electron:require('electron'),store,getWindow:()=>win});await service.restore('a');assert.equal(service.snapshot('a').tabs[0].state,'suspended');assert.equal((await service.profile.cookies.get({url,name:'login'}))[0].value,'fixture')
 console.log('SHARED_BROWSER_PASSED')
}
main().then(()=>app.exit(0)).catch(e=>{console.error(e.stack);app.exit(1)}).finally(()=>{server?.close();service?.dispose();win?.destroy()})
